INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & transmission model', '[["Invoice format", "Structured XML, submitted exclusively through the state IS ESF platform"], ["Transmission model", "Real-time pre-validation clearance (CTC) -- IS ESF validates and assigns a registration number before the invoice reaches the buyer"], ["Digital signature", "Qualified electronic signature via an accredited National Certification Authority (NUC RK) certificate"], ["Peer-to-peer exchange", "Not permitted -- every invoice must route through IS ESF"]]', 'Whether IS ESF accepts only XML with no alternative format is sourced only via a single AI-summarized secondary briefing in this research round, not independently cross-checked against the primary Order No. 629/Tax Code text -- treat as plausible, not confirmed.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Legal framework evolution', '[["2014-2018", "Voluntary rules under Government Resolutions No. 818 and No. 573, then Order No. 270 under the 2018 Tax Code"], ["2019-2025", "Order No. 370 (22 Apr 2019, retroactive to 1 Jan 2019) governs the mandatory era, amended repeatedly through Order No. 1321 (26 Dec 2023)"], ["From 2026", "New Tax Code (Law No. 214-VIII) plus Order No. 629 (28 Oct 2025) replace the prior framework entirely"]]', 'Order No. 629''s exact Adilet legal-database page could not be independently fetched in this research round (robots/SSL errors on every attempt) -- its order number and date are corroborated by two independent secondary industry sources, but direct primary-source verification is still recommended.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who must issue e-invoices', '[["VAT-registered taxpayers", "Universal requirement since 1 Jan 2019 (2017 Tax Code); recodified at Art. 207 of the new Tax Code from 2026"], ["Non-VAT-payer categories (from 2026)", "~12 categories under Art. 208-209: commission/forwarding agents, customs representatives/carriers, simplified-regime taxpayers, medical/pharma sellers, law offices, importers, Virtual Warehouse participants, and others"], ["Explicitly excluded", "Individuals selling personal property; private practitioners/sole entrepreneurs acting in that capacity; most retail sales via cash register (with exceptions for excisable/imported/listed goods)"], ["Revenue threshold", "None on the e-invoicing obligation itself, but the underlying VAT registration threshold dropped to 10,000 MRP for 2026"]]', NULL, NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 1, 'pills' FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The clearance flow', 'A compliant IS ESF invoice moves through this sequence:', 'Only an invoice IS ESF has validated and assigned a registration number is legally valid for the buyer -- direct delivery outside the platform has no effect.');
