INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'From 2026: buyer''s VAT-credit eligibility depends on active confirmation of the invoice within IS ESF before the VAT return is filed');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚠️ Penalties under Administrative Offences Code Art. 280-1', NULL, NULL, 'Kazakhstan sanctions e-invoicing violations under Article 280-1 of the Code of Administrative Offences (base Code: Law No. 235-V, 5 July 2014). First-offense failure to issue or late issuance draws a warning; repeat violations within a year draw tiered fines by business size -- roughly 40-150 MRP for repeat failure-to-issue (small/medium/large business), and 20-100 MRP for repeat late issuance. Missing accompanying export documents draws a flat 50 MRP first offense, 100 MRP on repeat. At the 2026 MRP value (KZT 4,325), a 40 MRP small-business fine equals roughly KZT 173,000. These figures are corroborated by two independent secondary legal-aggregator sites with matching structure, but neither is Kazakhstan''s own primary Adilet statutory text -- treat as plausible pending direct verification.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💳 VAT-credit tied to e-invoice confirmation', NULL, NULL, 'From 2026, a new mechanism reportedly ties VAT-credit eligibility directly to e-invoicing compliance: input VAT can only be credited where the specific e-invoice is actively confirmed within IS ESF before the VAT return is filed. Separately, one secondary source describes a further 2026 enforcement mechanism allowing temporary suspension of a taxpayer''s IS ESF access for unaddressed system notifications, which would effectively block invoicing entirely -- this suspension mechanism is not independently confirmed against a primary Tax Code citation and should be treated as unverified.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔍 What we could not confirm', NULL, NULL, 'Four items are flagged from this research round rather than presented as settled fact: (1) the exact current public-facing IS ESF portal domain -- search results surfaced both an "esf.gov.kz" reference and what appears to be an unrelated phishing-clone domain, so no unverified portal URL is cited on this page; (2) whether IS ESF genuinely accepts XML only, with no alternative format, sourced only via a single AI-summarized briefing; (3) exact issuance-deadline day-counts and the system-downtime paper-invoice exception, same single-source caveat; (4) whether a standalone, separately-dated pre-2019 "risk goods" mandatory e-invoicing wave exists ahead of the general 2019 mandate -- no independently-sourced date for this could be found, so no such milestone is included on this page.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your VAT-payer status and IS ESF registration', 'E-invoicing has been mandatory for all VAT-registered taxpayers in Kazakhstan since 1 January 2019 -- confirm your business is registered for IS ESF access and holds a valid NUC RK digital certificate.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you are not VAT-registered, check the new Tax Code''s non-VAT-payer categories', 'From 1 January 2026, roughly a dozen non-VAT-registered categories (commission/forwarding agents, customs representatives, simplified-regime taxpayers, medical/pharma sellers, law offices, importers, and more) must also issue e-invoices -- review Articles 208-209 to see if your activity is now in scope.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Update invoicing software for Order No. 629''s new fields and buyer-confirmation workflow', 'The new e-invoice form and rules, effective 1 January 2026, add fields (VAT-registration date, National Product Catalogue codes, advocate/non-resident supplier categories) and require mandatory buyer confirmation for corrected or cancelled invoices.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Re-check your VAT registration against the lowered 10,000 MRP threshold', 'The 2026 VAT registration threshold dropped to roughly KZT 40-43 million in annual turnover (from about KZT 73-75 million) -- businesses near the old threshold should re-check whether they are now required to register, and therefore to e-invoice.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'KZ';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Verify the current IS ESF portal domain directly with the State Revenue Committee', 'Search results for the IS ESF platform surfaced conflicting/unofficial domains alongside the genuine one -- confirm the correct current login URL through kgd.gov.kz''s own e-invoicing section rather than a search result, before connecting any credentials.');
